import json
from collections import Counter
def transform(grid):
    g=[r[:] for r in grid]; H,W=len(g),len(g[0])
    cnt=Counter(v for row in g for v in row)
    bg=cnt.most_common(1)[0][0]
    frame=[c for c in cnt if c!=bg][0]
    cells=[(r,c) for r in range(H) for c in range(W) if g[r][c]==frame]
    r0=min(r for r,c in cells); r1=max(r for r,c in cells)
    c0=min(c for r,c in cells); c1=max(c for r,c in cells)
    for r in range(r0,r1+1):
        for c in (c0,c1):
            if g[r][c]==bg: g[r][c]=2
    for c in range(c0,c1+1):
        for r in (r0,r1):
            if g[r][c]==bg: g[r][c]=2
    # extra: interior columns dense with frame cells get gaps between topmost/bottommost filled
    for c in range(c0+1,c1):
        rs=[r for r in range(H) if g[r][c]==frame]
        if len(rs)>=2:
            span=rs[-1]-rs[0]+1
            if len(rs)/span>=0.5:
                for r in range(rs[0]+1,rs[-1]):
                    if g[r][c]==bg: g[r][c]=2
    return g
